<div style="display: table-cell; vertical-align: top;"><strong style="display: block; margin-bottom: 5px;">Muntatge i Programació (40')</strong>
<p style="margin: 0;">Integració del sensor ultrasònic al sistema de la barrera.</p>
<pre class="code-block"><code>long duration;
int distance;

void loop() {
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  duration = pulseIn(echoPin, HIGH);
  distance = duration * 0.034 / 2;

  if (distance < 10) {
    myServo.write(90);  // Obrir barrera
  } else {
    myServo.write(0);   // Tancar barrera
  }
}</code></pre>
